TableData.Query:
SELECT num,ccy,
${if(len(rpunit) == 0,"balance","balance/'" + rpunit+"'")
} balance,
${if(len(rpunit) == 0,"balancecny","balancecny/'" + rpunit+"'")
} balancecny,
${if(len(rpunit) == 0,"balanceusd","balanceusd/'" + rpunit+"'")
} balanceusd,
parentbrca parentbrca,
brca brca
FROM t_acc_gl acc_gl
WHERE importdate='${rpdate}'
${if(len(brca) == 0,"","and parentbrca = '" + brca + "'")} 
and balance<>0
